export type MomentPlay={user:string;event:string;slot:number;card:string;fighter:string;bout:string;red:string;blue:string;state:'pending'|'settled';payout:number;result:string;created:number;settled:number|null};
export const momentRules={slots:3,win:40,finish:25,roundOne:15};
export function momentBonus(bout:FantasyBout,fighter:string){if(bout.outcome==='pending')return null;if(bout.outcome!=='finished'||bout.winner!==fighter)return{payout:0,result:bout.outcome==='finished'?'Loss':bout.outcome==='nc'?'No contest':bout.outcome==='draw'?'Draw':'Cancelled / replaced'};const finish=/submission|\bTKO\b|\bKO\b/i.test(bout.method);const payout=40+(finish?25:0)+(finish&&bout.round===1?15:0);return{payout,result:`Win${finish?' + finish':''}${finish&&bout.round===1?' + round one':''}`};}
export function validateMomentPlays(event:FantasyEvent,cards:string[],owned:string[],now=Date.now()):string|null{
 if(event.replay||now>=event.startsAt)return'This event is locked. Choose an upcoming official card.';
 if(cards.length>3||new Set(cards).size!==cards.length)return'Play up to three different Moments.';
 const fighters=new Set<string>(),bouts=new Set<string>();
 for(const id of cards){const card=moments.find(m=>m.id===id);if(!card||!owned.includes(id))return'Collect each Moment before playing it.';const bout=event.bouts.find(b=>b.outcome==='pending'&&(b.red.id===card.fighter||b.blue.id===card.fighter));if(!bout)return'That fighter is not available on this event.';if(fighters.has(card.fighter)||bouts.has(bout.id))return'Choose different fighters from different bouts.';fighters.add(card.fighter);bouts.add(bout.id);}
 return null;
}
